                newStateToAction.StateId = stateRequirement.id.ToString();
                newStateToAction.GameId = gameId.ToString();
                newStateToAction.Cost = stateRequirement.costPoinst;
                newStateToAction.Addition = stateRequirement.additionalPoinst;
                _context.StatesToActions.Add(newStateToAction);


                TeamHistoryMoves myMove = new TeamHistoryMoves();
                myMove.GameId = gameId.ToString();
                myMove.Teamid = teamId.ToString();
                myMove.Userid = myuser.Id.ToString();
