                SaveQuestionAndAnswers(campaign, db, dbCampaign);

                if (campaign.IsNew)
                {
                    dbCampaign.Question = null;
                    db.Campaigns.Add(dbCampaign);
                }
                else
                {
                    var currentCampaign = db.Campaigns.Include(x => x.Question).Include(x => x.Question.Answers).FirstOrDefault(x => x.Id == campaign.Id);
                    db.Entry(currentCampaign).CurrentValues.SetValues(dbCampaign);
                }
                if (!campaign.IsNew)
                {
                    var existingAnswers = db.Answers.Where(x => x.Question.Id == campaign.QuestionId).ToList();
                    foreach (var answer in existingAnswers)
                    {
                        var forRemove = campaign.Question.Answers.Find(x => !x.IsNew && answer.Id == x.Id);
                        if (forRemove == null)
                            db.Answers.Remove(answer);
                    }
                }

                db.SaveChanges();
